using System.Windows; using System.Windows.Controls; using SaarOSS.Rechnungsprogramm.Models; using SaarOSS.Rechnungsprogramm.Services; namespace SaarOSS.Rechnungsprogramm.Views; public partial class SettingsView:UserControl { private readonly CompanySettingsService _service=new(); public SettingsView(){InitializeComponent();LoadValues();} private void LoadValues(){var x=_service.Load();CompanyNameBox.Text=x.CompanyName;OwnerNameBox.Text=x.OwnerName;StreetBox.Text=x.Street;PostalCodeBox.Text=x.PostalCode;CityBox.Text=x.City;EmailBox.Text=x.Email;PhoneBox.Text=x.Phone;TaxNumberBox.Text=x.TaxNumber;VatIdBox.Text=x.VatId;IbanBox.Text=x.Iban;PaymentTermBox.Text=x.PaymentTermDays.ToString();SmallBusinessBox.IsChecked=x.IsSmallBusiness;StatusText.Text="";} private void SaveSettings(object sender,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(CompanyNameBox.Text)){MessageBox.Show("Bitte geben Sie einen Unternehmensnamen ein.","Eingabe prüfen",MessageBoxButton.OK,MessageBoxImage.Warning);CompanyNameBox.Focus();return;}if(!int.TryParse(PaymentTermBox.Text,out var days)||days<0||days>365){MessageBox.Show("Das Zahlungsziel muss zwischen 0 und 365 Tagen liegen.","Eingabe prüfen",MessageBoxButton.OK,MessageBoxImage.Warning);PaymentTermBox.Focus();return;}var x=new CompanySettings{CompanyName=CompanyNameBox.Text.Trim(),OwnerName=OwnerNameBox.Text.Trim(),Street=StreetBox.Text.Trim(),PostalCode=PostalCodeBox.Text.Trim(),City=CityBox.Text.Trim(),Email=EmailBox.Text.Trim(),Phone=PhoneBox.Text.Trim(),TaxNumber=TaxNumberBox.Text.Trim(),VatId=VatIdBox.Text.Trim(),Iban=IbanBox.Text.Replace(" ","").Trim(),PaymentTermDays=days,IsSmallBusiness=SmallBusinessBox.IsChecked==true};try{_service.Save(x);StatusText.Text="✓ Sicher gespeichert";}catch(Exception ex){MessageBox.Show("Die Unternehmensdaten konnten nicht gespeichert werden.\n\n"+ex.Message,"Speicherfehler",MessageBoxButton.OK,MessageBoxImage.Error);}} private void ReloadSettings(object sender,RoutedEventArgs e)=>LoadValues();  private void OpenTaxProfile(object sender,System.Windows.RoutedEventArgs e){new TaxProfileWindow(){Owner=System.Windows.Window.GetWindow(this)}.ShowDialog();}
 private void OpenDocumentDesign(object sender,System.Windows.RoutedEventArgs e){new DocumentDesignWindow(){Owner=System.Windows.Window.GetWindow(this)}.ShowDialog();}
 private void OpenPaymentFooter(object sender,System.Windows.RoutedEventArgs e){new PaymentFooterWindow(){Owner=System.Windows.Window.GetWindow(this)}.ShowDialog();}
 private void OpenLocalDataReset(object sender,System.Windows.RoutedEventArgs e){new LocalDataResetWindow(){Owner=System.Windows.Window.GetWindow(this)}.ShowDialog();LoadValues();} 
}
